// Chamada: self.db.transaction()
// Fonte (nível 3): sociality-mcp/packages/social-core/src/social_core/db.py:52-65
    def transaction(self) -> Any:
        connection = self.connect()
        outer = connection.in_transaction
        if not outer:
            connection.execute("BEGIN")
        try:
            yield connection
        except Exception:
            if connection.in_transaction and not outer:
                connection.rollback()
            raise
        else:
            if connection.in_transaction and not outer:
                connection.commit()

