    ) -> list[dict[str, Any]]:
        matches = self.search_matches(season=season, competition=competition)
        goals: dict[str, int] = {}
        for m in matches:
            goals[m["home_team"]] = goals.get(m["home_team"], 0) + m["home_goal"]
