// Fonte (nível 3): kubectl_mcp_tool/crd_detector.py:129-146
def crd_exists(crd_name: str, context: str = "") -> bool:
    """Check if a specific CRD exists in the cluster.

    Args:
        crd_name: Full CRD name (e.g., "certificates.cert-manager.io")
        context: Kubernetes context to use

    Returns:
        True if CRD exists, False otherwise
    """
    try:
        cmd = ["kubectl"] + _get_kubectl_context_args(context) + [
            "get", "crd", crd_name, "-o", "name"
        ]
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
        return result.returncode == 0
    except Exception:
        return False

// Chamada: _virtctl_available()
// Fonte (nível 3): kubectl_mcp_tool/tools/kubevirt.py:31-38
def _virtctl_available() -> bool:
    """Check if virtctl CLI is available."""
    try:
        result = subprocess.run(["virtctl", "version", "--client"],
                                capture_output=True, timeout=5)
        return result.returncode == 0
    except Exception:
        return False

// Chamada: _run_virtctl(["unpause", "vm", name, "-n", namespace], context)
// Fonte (nível 3): kubectl_mcp_tool/tools/kubevirt.py:41-58
def _run_virtctl(args: List[str], context: str = "") -> Dict[str, Any]:
    """Run virtctl command if available."""
    if not _virtctl_available():
        return {"success": False, "error": "virtctl CLI not available"}

    cmd = ["virtctl"] + args
    if context:
        cmd.extend(["--context", context])

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
        if result.returncode == 0:
            return {"success": True, "output": result.stdout}
        return {"success": False, "error": result.stderr}
    except subprocess.TimeoutExpired:
        return {"success": False, "error": "Command timed out"}
    except Exception as e:
        return {"success": False, "error": str(e)}

