func usergroupsListHandler(ctx context.Context, _ *mcp.CallToolRequest, _ usergroupsListInput) (*mcp.CallToolResult, any, error) {
	sc := storageContextFrom(ctx)
	if sc == nil {
		return nil, nil, fmt.Errorf("unauthorized: missing auth context")
	}

	groups, err := models.GetUserGroupsByOrgID(sc.GetOrgID())
	if err != nil {
		return nil, nil, fmt.Errorf("failed listing user groups: %w", err)
	}
	// Same union as GET /users/groups, or an agent cannot see a group that only
	// exists as an access_control permission and calls usergroups_create on a
	// name that already grants access (EVL-217).
	pluginGroups, err := models.ListAccessControlGroupNames(models.DB, sc.GetOrgID())
	if err != nil {
		return nil, nil, fmt.Errorf("failed listing user groups: %w", err)
	}

	// Deduplicate group names
	seen := make(map[string]bool)
	names := make([]string, 0)
	for _, g := range groups {
		if !seen[g.Name] {
			seen[g.Name] = true
			names = append(names, g.Name)
		}
	}
	for _, name := range pluginGroups {
		if !seen[name] {
			seen[name] = true
			names = append(names, name)
		}
	}
	slices.Sort(names)

	return jsonResult(names)
}

