def unique(items: Iterable[str]) -> list[str]:
    """Order-preserving de-duplication (used for alias lists)."""

    seen: set[str] = set()
    out: list[str] = []
    for item in items:
        if item not in seen:
            seen.add(item)
            out.append(item)
    return out

