  const isOwner = await branchRepo.isOwner(branch.branch_id as BranchID, userId);
  const effective = await branchRepo.resolveUserPermission(branch, userId);
  return hasBranchPermission(
    branch,
    userId,
    isOwner,
    'all',
    ctx.authenticatedUser?.role,
    true,
