        bool wasPreviewVisible = preBbox.IsValid && preBbox.Diagonal.Length > 0;

        try
        {
            ghDoc.NewSolution(true);

            bool shouldZoom = zoom_views ?? !wasPreviewVisible;
            if (shouldZoom) ZoomViewsToPreview(rhinoDoc, ghDoc);
        }
        catch (Exception ex)
