            return ex.Message;
        }

        var statuses = GH1_Utils.GetCanvasStatus(ghDoc);
        if (statuses.Count == 0)
        {
            return "Success";
        }

        string errMsg = "Solution encountered some errors";

        return JsonSerializer.Serialize(new { errMsg, statuses });
    }

