        elif mem_str.endswith("K"):
            return int(mem_str[:-1]) * 1000
        elif mem_str.endswith("M"):
            return int(mem_str[:-1]) * 1000000
        elif mem_str.endswith("G"):
            return int(mem_str[:-1]) * 1000000000
        else:
            return int(mem_str)
    except (ValueError, TypeError):
