def _prettify(base: str) -> str:
    """Title-case fallback display name for clubs not in the curated map."""
    small = {"de", "do", "da", "dos", "das", "e"}
    parts = base.split()
    out = []
    for i, p in enumerate(parts):
        if i and p in small:
            out.append(p)
        else:
            out.append(p.capitalize())
    return " ".join(out) if out else base

