// Chamada: _record_from_matches(matches, team)
// Fonte (nível 2): experiments/adrianco/experiment-4/runs/language=python_model=claude-opus-4-8_tooling=beads/rep1/brazilian_soccer_mcp/queries.py:222-254
def _record_from_matches(matches: Iterable[Match], team: str) -> dict:
    wins = draws = losses = gf = ga = played = 0
    for m in matches:
        if not m.has_score:
            continue
        side = _team_involved(m, team)
        if side is None:
            continue
        played += 1
        if side == "home":
            tf, ta = m.home_goal, m.away_goal
        else:
            tf, ta = m.away_goal, m.home_goal
        gf += tf
        ga += ta
        if tf > ta:
            wins += 1
        elif tf < ta:
            losses += 1
        else:
            draws += 1
    win_rate = round(100.0 * wins / played, 1) if played else 0.0
    return {
        "matches": played,
        "wins": wins,
        "draws": draws,
        "losses": losses,
        "goals_for": gf,
        "goals_against": ga,
        "goal_difference": gf - ga,
        "points": wins * 3 + draws,
        "win_rate": win_rate,
    }

