// Fonte (nível 3): src/core/tools/agent-tools.ts:348-397
  async createAgent(params: {
    name: string;
    role: string;
    workspaceId: string;
    parentId?: string;
    modelTier?: string;
    metadata?: Record<string, string>;
  }): Promise<ToolResult> {
    const role = params.role.toUpperCase() as AgentRole;
    if (!Object.values(AgentRole).includes(role)) {
      return errorResult(
        `Invalid role: ${params.role}. Must be one of: ${Object.values(AgentRole).join(", ")}`
      );
    }

    const modelTier = params.modelTier
      ? (params.modelTier.toUpperCase() as ModelTier)
      : ModelTier.SMART;

    const agent = createAgentModel({
      id: uuidv4(),
      name: params.name,
      role,
      workspaceId: params.workspaceId,
      parentId: params.parentId,
      modelTier,
      metadata: params.metadata ?? {},
    });

    await this.agentStore.save(agent);

    this.eventBus.emit({
      type: AgentEventType.AGENT_CREATED,
      agentId: agent.id,
      workspaceId: agent.workspaceId,
      data: {
        name: agent.name,
        role: agent.role,
        metadata: agent.metadata,
      },
      timestamp: new Date(),
    });

    return successResult({
      agentId: agent.id,
      name: agent.name,
      role: agent.role,
      status: agent.status,
    });
  }

