export function classifyBranchFilesystemReadiness(
  branch: Pick<Branch, 'archived' | 'filesystem_status'>
): BranchFilesystemReadinessState {
  if (branch.archived) return 'unavailable';

  switch (branch.filesystem_status) {
    case undefined:
    case 'ready':
      return 'ready';
    case 'creating':
      return 'pending';
    case 'failed':
      return 'failed';
    case 'preserved':
    case 'cleaned':
    case 'deleted':
      return 'unavailable';
  }
}

