	pub fn next(&mut self) -> Option<Result<Token, LexError>> {
		if self.read == self.write {
			return self.lex_token();
		}
		let res =
			unsafe { self.peek.get_unchecked((self.read & Self::MASK) as usize).assume_init() };
		self.read = self.read.wrapping_add(1);
		Some(res)
	}

