// Chamada: buildSystemPrompt(ctx)
// Fonte (nível 3): packages/core/src/agent/system-prompt.ts:9-38
export function buildSystemPrompt(ctx: PromptContext): string {
  return `You are the Knowledge Keeper — an agent that manages a knowledge base conforming to the Open Knowledge Format (OKF) v0.1 specification.

## The OKF format (what you are managing)

- The knowledge base ("bundle") is a directory tree of markdown files.
- Every concept is one .md file with YAML frontmatter. The only REQUIRED field is \`type\` (a free-form string naming the kind of thing, e.g. "BigQuery Table", "API Endpoint", "Playbook", "Decision", "How-To"). Recommended fields: \`title\`, \`description\` (one line), \`resource\` (canonical URI of the underlying asset, if any), \`tags\` (list).
- \`index.md\` and \`log.md\` are RESERVED filenames — never create concepts with those names. They are maintained automatically by the system after your writes; you never edit them.
- Cross-link related concepts with bundle-relative markdown links: \`[Customers table](/tables/customers.md)\`. Link liberally; broken links are tolerated.
- Body convention: prose first, then optional \`# Schema\`, \`# Examples\`, \`# Citations\` sections where they apply. Citations are numbered: \`[1] [Title](https://url)\`.

## Operating rules

1. SEARCH FIRST. Before adding anything, search for existing concepts the new knowledge relates to — both overlap (is this already covered?) and ownership (which existing entity does this fact belong to?).
2. ENRICH OVER CREATE. A fact that is an attribute or detail of an existing concept gets patched INTO that concept (read it first, then extend its body or a fitting section) — not filed as its own concept. Create a new concept only when the knowledge is a distinct entity or topic someone would look up on its own, or is substantial enough that embedding it would dominate the host concept.
3. LINK BOTH WAYS. A new concept must be wired into the graph, not dropped in isolation: link it to related concepts, AND patch those related concepts to reference it back where the relationship genuinely matters (an owning entity should mention what it owns). An unlinked concept is invisible knowledge.
4. REUSE TYPES. Prefer a type already in use over inventing a synonym. Types currently in the bundle: ${ctx.existingTypes.length ? ctx.existingTypes.join(", ") : "(none yet — you set the precedent; choose short, reusable names)"}.
5. PLACE DELIBERATELY. Choose directories by subject area (e.g. /tables/, /apis/, /playbooks/, /decisions/). Reuse existing directories when they fit; create new ones only for genuinely new areas. Filenames: short kebab-case, .md extension.
6. WRITE FOR THE NEXT READER. Frontmatter \`description\` is one crisp line. Bodies are concise, factual, and self-contained — a reader landing on one file with no other context should understand it.
7. PREFER PATCH OVER REWRITE. For small changes to an existing concept, use patch_concept (frontmatter merge or single-section replace) instead of rewriting the whole file with write_concept.
8. DEPRECATE, DON'T DELETE. Prefer tagging a concept \`deprecated\` (and saying why in the body) over delete_concept. Delete only when the content is wrong/harmful or the user explicitly asks.
9. LOG SUMMARIES. Every mutation tool takes a log_summary — one past-tense sentence describing the change, with bundle-relative links to the concepts touched, e.g. "Added [Billing API](/apis/billing-api.md) covering charge endpoints."
10. CITE WHEN ANSWERING. When answering questions, ground every claim in concepts you actually read, and list their bundle paths. If the knowledge base doesn't contain the answer, say so plainly — never invent knowledge.

## Current bundle layout

${ctx.treeSummary || "(empty bundle)"}

${modeSection(ctx.mode)}`;
}

// Chamada: buildReadTools(kb, recorder)
// Fonte (nível 3): packages/core/src/agent/tools.ts:30-83
export function buildReadTools(kb: KnowledgeBase, trace?: TraceRecorder) {
  return {
    search_knowledge: tool({
      description:
        "Search the knowledge base by keywords, optionally filtered by concept type and/or tags. Returns ranked hits with paths and snippets. NOTE: matching is keyword-based, not semantic — a miss does NOT mean the knowledge is absent; it may be worded differently.",
      inputSchema: z.object({
        query: z.string().describe("Keywords to search for. May be empty when filtering by type/tags only."),
        type: z.string().optional().describe("Exact concept type filter"),
        tags: z.array(z.string()).optional().describe("Require ALL of these tags"),
      }),
      execute: async ({ query, type, tags }) => {
        const hits = await kb.search(query, { type, tags });
        trace?.record("search_knowledge", query, hits.map((h) => h.path));
        if (hits.length > 0) return hits;
        // Keyword miss ≠ knowledge absent. Put the map in the tool result so
        // the model's next step is to read plausible concepts, not give up.
        const tree = formatTree(await kb.listTree());
        return {
          hits: [],
          notice:
            "No keyword matches — but this search is literal, not semantic. The knowledge may exist under different wording. Before concluding it is absent: (1) retry with 1-2 synonyms or broader terms, (2) review the layout below and read_concept ANY concept whose type, name, or description could plausibly relate to the question.",
          bundle_layout: tree,
        };
      },
    }),
    read_concept: tool({
      description: "Read one concept document in full: frontmatter and markdown body.",
      inputSchema: z.object({ path: conceptPath }),
      execute: async ({ path }) => {
        const c = await kb.readConcept(path);
        trace?.record("read_concept", c.path, [c.path]);
        return { path: c.path, frontmatter: c.frontmatter, body: c.body };
      },
    }),
    list_directory: tool({
      description:
        "List the bundle's directory tree with concept types/titles/descriptions. Use to understand structure and decide where new concepts belong.",
      inputSchema: z.object({}),
      execute: async () => {
        trace?.record("list_directory", "", []);
        return formatTree(await kb.listTree());
      },
    }),
    lint_knowledge: tool({
      description:
        "Graph health check: orphaned concepts (nothing links to them) and broken links. Use to find what needs wiring into the graph or fixing.",
      inputSchema: z.object({}),
      execute: async () => {
        trace?.record("lint_knowledge", "", []);
        return kb.lint();
      },
    }),
  };
}

// Chamada: buildWriteTools(kb, filesChanged, recorder)
// Fonte (nível 3): packages/core/src/agent/tools.ts:85-162
export function buildWriteTools(kb: KnowledgeBase, filesChanged: Set<string>, trace?: TraceRecorder) {
  return {
    write_concept: tool({
      description:
        "Create a new concept or fully overwrite an existing one. Frontmatter must include a non-empty 'type'. index.md and log.md maintenance is automatic — never write those.",
      inputSchema: z.object({
        path: conceptPath,
        frontmatter: frontmatterSchema,
        body: z.string().describe("Markdown body (no frontmatter block)"),
        log_summary: logSummary,
      }),
      execute: async ({ path, frontmatter, body, log_summary }) => {
        const c = await kb.writeConcept(path, frontmatter, body, log_summary);
        filesChanged.add(c.path);
        recordHotWrite(c.path);
        trace?.record("write_concept", c.path, [c.path], true);
        return { written: c.path };
      },
    }),
    patch_concept: tool({
      description:
        "Targeted update of an existing concept: merge frontmatter keys (null deletes a key) and/or replace one top-level '# Section' body section. Prefer this over write_concept for small edits.",
      inputSchema: z.object({
        path: conceptPath,
        frontmatter: z
          .record(z.unknown())
          .optional()
          .describe("Frontmatter keys to merge; set a key to null to remove it"),
        replace_section: z
          .object({
            heading: z
              .string()
              .min(1)
              .describe("Top-level heading name, e.g. 'Schema'. Must be non-empty — to replace the whole body use replace_body instead."),
            content: z.string().describe("New content for that section"),
          })
          .optional(),
        replace_body: z
          .string()
          .optional()
          .describe("Replace the entire markdown body (frontmatter untouched). Use for restructuring; prefer replace_section for targeted edits."),
        log_summary: logSummary,
      }),
      execute: async ({ path, frontmatter, replace_section, replace_body, log_summary }) => {
        const c = await kb.patchConcept(
          path,
          {
            frontmatter,
            replaceSection: replace_section
              ? { heading: replace_section.heading, content: replace_section.content }
              : undefined,
            replaceBody: replace_body,
          },
          log_summary
        );
        filesChanged.add(c.path);
        recordHotWrite(c.path);
        trace?.record("patch_concept", c.path, [c.path], true);
        return { patched: c.path };
      },
    }),
    delete_concept: tool({
      description:
        "Permanently delete a concept file. Prefer deprecation (tag 'deprecated' via patch_concept) unless content is wrong/harmful or deletion was explicitly requested.",
      inputSchema: z.object({
        path: conceptPath,
        log_summary: logSummary,
      }),
      execute: async ({ path, log_summary }) => {
        await kb.deleteConcept(path, log_summary);
        filesChanged.add(path);
        recordHotDelete(path);
        trace?.record("delete_concept", path, [path], true);
        return { deleted: path };
      },
    }),
  };
}

