async def get_monarch_client() -> MonarchMoney:
    """Get or create a cached MonarchMoney client using secure session storage.

    Authentication is established only via ``login_setup.py`` (or the
    elicitation login tools), which save a session to the system keyring. MCP
    tool calls never initiate a noninteractive password login, so a stray set
    of environment credentials cannot trigger an unattended sign-in.
    """
    global _cached_client

    if _cached_client is not None:
        return _cached_client

    client = secure_session.get_authenticated_client()

    if client is not None:
        logger.info("Using authenticated client from secure keyring storage")
        _cached_client = client
        return client

    raise RuntimeError("Authentication needed! Run: python login_setup.py")

// Chamada: secure_session.get_authenticated_client()
// Fonte (nível 3): src/monarch_mcp_server/secure_session.py:233-272
    def get_authenticated_client(self) -> Optional[MonarchMoney]:
        """Get an authenticated MonarchMoney client.

        Prefers cookie auth when cookies are present, falling back to the
        token + device_uuid path otherwise. Returns None if no usable
        session is stored.
        """
        session = self.load_session()
        if not session:
            return None

        auth_mode = session.get("auth_mode", "token")
        cookies = session.get("cookies")
        token = session.get("token")

        try:
            if auth_mode == "cookie" and isinstance(cookies, dict) and cookies:
                client = create_monarch_client(
                    token=token, device_uuid=session.get("device_uuid")
                )
                # set_cookies pops Authorization and sets the cookie-mode
                # web headers (Origin, Referer, monarch-client, X-Csrftoken).
                client.set_cookies(cookies)
                logger.info("✅ MonarchMoney client created with stored cookies")
                return client

            if not token:
                logger.warning(
                    "⚠️  Session has no token and no cookies; treating as missing"
                )
                return None

            client = create_monarch_client(
                token=token, device_uuid=session.get("device_uuid")
            )
            logger.info("✅ MonarchMoney client created with stored token")
            return client
        except Exception as e:
            logger.error(f"❌ Failed to create MonarchMoney client: {e}")
            return None

