    public static string SecondaryListingUnavailable(
        CommonStock stock,
        string requestedTicker,
        string dataset
    )
    {
        if (!SecondaryTickerPolicy.IsSecondarySymbol(stock, requestedTicker))
            return null;

        var listedTicker = SecondaryTickerPolicy.ResolveListedTicker(stock, requestedTicker);
        return $"No exact {dataset} series is available for {listedTicker}. It is a separate "
            + $"listing on the same SEC filer as {stock.Ticker} ({stock.Name}); {stock.Ticker}'s "
            + "FINRA rows are not substituted.";
    }

// Chamada: SecondaryTickerPolicy.IsSecondarySymbol(stock, requestedTicker)
// Fonte (nível 3): src/Equibles.CommonStocks.Data/Helpers/SecondaryTickerPolicy.cs:64-68
    public static bool IsSecondarySymbol(CommonStock stock, string requestedTicker)
    {
        var resolved = ResolveListedTicker(stock, requestedTicker);
        return resolved != null && !string.Equals(resolved, stock.Ticker, StringComparison.Ordinal);
    }

// Chamada: SecondaryTickerPolicy.ResolveListedTicker(stock, requestedTicker)
// Fonte (nível 3): src/Equibles.CommonStocks.Data/Helpers/SecondaryTickerPolicy.cs:30-56
    public static string ResolveListedTicker(CommonStock stock, string requestedTicker)
    {
        if (stock?.Ticker == null || string.IsNullOrWhiteSpace(requestedTicker))
            return null;

        var requested = TickerNormalizer.Normalize(requestedTicker);
        if (requested == null)
            return null;

        var candidates = requested.Contains('.')
            ? new[] { requested, requested.Replace('.', '-') }
            : new[] { requested };

        foreach (var candidate in candidates)
        {
            if (string.Equals(stock.Ticker, candidate, StringComparison.Ordinal))
                return stock.Ticker;

            var secondary = (stock.SecondaryTickers ?? []).FirstOrDefault(ticker =>
                string.Equals(ticker, candidate, StringComparison.OrdinalIgnoreCase)
            );
            if (secondary != null)
                return secondary;
        }

        return null;
    }

