func resolveListDateDays(dateStr string, latest, maxLatest int) (string, int, error) {
	if dateStr != "" {
		parsed, err := episode.ParseDate(dateStr)
		if err != nil {
			return "", 0, err
		}
		return parsed, 1, nil
	}
	if latest <= 0 {
		latest = defaultFollowedLatest
	}
	if latest > maxLatest {
		return "", 0, fmt.Errorf("latest must be between 1 and %d", maxLatest)
	}
	return episode.Today(), latest, nil
}

// Chamada: episode.ParseDate(dateStr)
// Fonte (nível 3): internal/episode/followed.go:127-141
func ParseDate(s string) (string, error) {
	now := time.Now()
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "today":
		return now.Format("2006-01-02"), nil
	case "yesterday":
		return now.AddDate(0, 0, -1).Format("2006-01-02"), nil
	default:
		t, err := time.Parse("2006-01-02", s)
		if err != nil {
			return "", fmt.Errorf("invalid date %q: use today, yesterday, or YYYY-MM-DD", s)
		}
		return t.Format("2006-01-02"), nil
	}
}

