def _format_duration_label(secs: int) -> str:
    """Format seconds into a concise human-readable label (e.g. 5s, 2m, 1h)."""
    if secs < 60:
        return f"{secs}s"
    if secs < 3600:
        mins = secs // 60
        remainder = secs % 60
        if remainder:
            return f"{mins}m{remainder}s"
        return f"{mins}m"
    hours = secs // 3600
    remainder = (secs % 3600) // 60
    if remainder:
        return f"{hours}h{remainder}m"
    return f"{hours}h"

