// Chamada: c.do(ctx, http.MethodPost, path, recordedAtBody{RecordedAt: recordedAt}, &resp)
// Fonte (nível 3): cli/pkg/client/client.go:84-164
func (c *Client) do(ctx context.Context, method, path string, body, out any) error {
	var buf []byte
	if body != nil {
		b, err := json.Marshal(body)
		if err != nil {
			return fmt.Errorf("encoding request body: %w", err)
		}
		buf = b
	}

	attempt := func(jwt string) (*http.Response, error) {
		var reqBody io.Reader
		if buf != nil {
			reqBody = bytes.NewReader(buf)
		}
		req, err := http.NewRequestWithContext(ctx, method, c.BaseURL+path, reqBody)
		if err != nil {
			return nil, fmt.Errorf("building request: %w", err)
		}
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("Accept", "application/json")
		req.Header.Set("User-Agent", c.UserAgent)
		if jwt != "" {
			req.Header.Set("Authorization", "Bearer "+jwt)
		}
		return c.HTTPClient.Do(req)
	}

	c.mu.Lock()
	jwt := c.JWT
	c.mu.Unlock()
	resp, err := attempt(jwt)
	if err != nil {
		return err
	}

	if resp.StatusCode == http.StatusUnauthorized && c.refresher != nil {
		resp.Body.Close()
		newJWT, refreshErr := c.refreshAfter401(ctx, jwt)
		if refreshErr != nil {
			// Only a dead session maps to ErrUnauthorized ("log in again").
			// Anything else (server error, network failure) must surface as
			// itself, or a transient outage reads as an expired login.
			if errors.Is(refreshErr, ErrUnauthorized) || errors.Is(refreshErr, ErrInvalidGrant) {
				return ErrUnauthorized
			}
			return fmt.Errorf("refreshing the session after a 401: %w", refreshErr)
		}
		if newJWT == "" {
			return ErrUnauthorized
		}
		resp, err = attempt(newJWT)
		if err != nil {
			return err
		}
	}
	defer resp.Body.Close()

	if resp.StatusCode >= 200 && resp.StatusCode < 300 {
		if out == nil {
			return nil
		}
		if err := json.NewDecoder(resp.Body).Decode(out); err != nil {
			return fmt.Errorf("decoding response: %w", err)
		}
		return nil
	}

	switch resp.StatusCode {
	case http.StatusUnauthorized:
		return ErrUnauthorized
	case http.StatusForbidden:
		return ErrForbidden
	case http.StatusNotFound:
		return ErrNotFound
	case http.StatusTooManyRequests:
		return ErrRateLimited
	}
	respBody, _ := io.ReadAll(resp.Body)
	return &APIError{StatusCode: resp.StatusCode, Body: strings.TrimSpace(string(respBody))}
}

// Chamada: s.client(req)
// Fonte (nível 2): cli/pkg/mcpserver/common.go:47-60
func (s *server) client(req *mcp.CallToolRequest) *client.Client {
	if !s.cfg.PerRequestBearer || req == nil {
		return s.cfg.Client
	}
	extra := req.GetExtra()
	if extra == nil || extra.Header == nil {
		return s.cfg.Client
	}
	fields := strings.Fields(extra.Header.Get("Authorization"))
	if len(fields) != 2 || !strings.EqualFold(fields[0], "bearer") {
		return s.cfg.Client
	}
	return s.cfg.Client.WithBearer(fields[1])
}

