		HTTPClient: c.HTTPClient,
		JWT:        token,
		UserAgent:  c.UserAgent,
	}
}

// Chamada: s.apiErr(err)
// Fonte (nível 2): cli/pkg/mcpserver/common.go:32-45
func (s *server) apiErr(err error) error {
	c := errclass.Classify(err)
	hint := c.Hint
	if c.Code == "token_expired" {
		hint = s.cfg.AuthHint
		if hint == "" {
			hint = "run 'traceway login' in a terminal on the host, then reconnect this MCP server"
		}
	}
	if hint != "" {
		return fmt.Errorf("error=%s: %s. Hint: %s", c.Code, c.Message, hint)
	}
	return fmt.Errorf("error=%s: %s", c.Code, c.Message)
}

// Chamada: errclass.Classify(err)
// Fonte (nível 3): cli/internal/errclass/errclass.go:27-74
func Classify(err error) Classified {
	switch {
	case errors.Is(err, client.ErrUnauthorized):
		return Classified{
			Code: "token_expired", Message: "session expired or invalid",
			Hint:     "traceway login",
			ExitCode: exitcode.Auth,
		}
	case errors.Is(err, client.ErrForbidden):
		return Classified{
			Code: "forbidden", Message: "permission denied",
			ExitCode: exitcode.Auth,
		}
	case errors.Is(err, client.ErrNotFound):
		return Classified{
			Code: "not_found", Message: "resource not found",
			ExitCode: exitcode.NotFound,
		}
	case errors.Is(err, client.ErrRateLimited):
		return Classified{
			Code: "rate_limited", Message: "rate limit exceeded — slow down or retry later",
			ExitCode: exitcode.RateLimited,
		}
	}
	if apiErr, ok := errors.AsType[*client.APIError](err); ok {
		if apiErr.StatusCode >= 500 {
			return Classified{
				Code: "server_error", Message: apiErr.Error(),
				ExitCode: exitcode.Server,
			}
		}
		return Classified{
			Code: "api_error", Message: apiErr.Error(),
			ExitCode: exitcode.Generic,
		}
	}
	if urlErr, ok := errors.AsType[*url.Error](err); ok {
		return Classified{
			Code: "connection_failed", Message: urlErr.Error(),
			Hint:     "check that the Traceway URL is reachable and the network is up",
			ExitCode: exitcode.Connection,
		}
	}
