func (t timeRangeIn) resolve() (client.TimeRange, error) {
	tr, err := timerange.Resolve(t.Since, t.From, t.To)
	if err != nil {
		return client.TimeRange{}, usageErrf("%v. Use since like 30m, 1h, 7d (units s/m/h and integer d only), or from+to as RFC3339; not both", err)
	}
	return tr, nil
}

// Chamada: timerange.Resolve(t.Since, t.From, t.To)
// Fonte (nível 3): cli/internal/timerange/timerange.go:23-55
func Resolve(since, from, to string) (client.TimeRange, error) {
	if since != "" && (from != "" || to != "") {
		return client.TimeRange{}, fmt.Errorf("%w: since cannot be combined with from/to", ErrInvalid)
	}
	if (from != "") != (to != "") {
		return client.TimeRange{}, fmt.Errorf("%w: from and to must be used together", ErrInvalid)
	}

	if from != "" {
		fromT, err := time.Parse(time.RFC3339, from)
		if err != nil {
			return client.TimeRange{}, fmt.Errorf("%w: from: %v", ErrInvalid, err)
		}
		toT, err := time.Parse(time.RFC3339, to)
		if err != nil {
			return client.TimeRange{}, fmt.Errorf("%w: to: %v", ErrInvalid, err)
		}
		if toT.Before(fromT) {
			return client.TimeRange{}, fmt.Errorf("%w: from must not be after to", ErrInvalid)
		}
		return client.TimeRangeFromExplicit(fromT, toT), nil
	}

	dur := time.Hour
	if since != "" {
		d, err := ParseRelativeDuration(since)
		if err != nil {
			return client.TimeRange{}, fmt.Errorf("%w: since: %v", ErrInvalid, err)
		}
		dur = d
	}
	return client.TimeRangeFromSince(dur), nil
}

