def normalize_lab_path(path: str) -> str:
    """Ensure lab path has leading slash and .unl extension."""
    path = path.strip()
    if not path.startswith("/"):
        path = "/" + path
    if not path.endswith(".unl"):
        path += ".unl"
    return path

