// Chamada: _embedder.encode_query(query)
// Fonte (nível 3): semantic_search/embedder.py:74-101
    def encode_query(self, query: str) -> np.ndarray:
        """Encode a search query into an embedding vector."""
        text = self._format_query(query)

        try:
            response = self.client.embeddings.create(
                model=self.model,
                input=text,
                encoding_format="float",
                extra_headers={
                    "HTTP-Referer": "https://mevzuatmcp.com",
                    "X-Title": "Mevzuat MCP Server",
                }
            )

            embedding = np.array(response.data[0].embedding, dtype=np.float32)

            # L2 normalize for cosine similarity
            norm = np.linalg.norm(embedding)
            if norm > 0:
                embedding = embedding / norm

            logger.debug(f"Encoded query: {query[:50]}... -> shape: {embedding.shape}")
            return embedding

        except Exception as e:
            logger.error(f"Failed to encode query: {e}")
            raise

// Chamada: vector_store.search(query_embedding, top_k=max_results, threshold=threshold)
// Fonte (nível 3): semantic_search/vector_store.py:67-104
    def search(self,
              query_embedding: np.ndarray,
              top_k: int = 10,
              threshold: Optional[float] = None) -> List[Tuple[Document, float]]:
        if not self.index_built or self.embeddings is None:
            return []

        if len(query_embedding.shape) == 1:
            query_embedding = query_embedding.reshape(1, -1)

        similarities = np.dot(self.embeddings, query_embedding.T).squeeze()

        if threshold is not None:
            valid_indices = np.where(similarities >= threshold)[0]
            if len(valid_indices) == 0:
                return []
            similarities = similarities[valid_indices]
            valid_docs = [self.documents[i] for i in valid_indices]
        else:
            valid_docs = self.documents

        top_k = min(top_k, len(valid_docs))
        if top_k == 0:
            return []

        if len(similarities) > top_k:
            top_indices = np.argpartition(similarities, -top_k)[-top_k:]
            top_indices = top_indices[np.argsort(similarities[top_indices])[::-1]]
        else:
            top_indices = np.argsort(similarities)[::-1]

        results = []
        for idx in top_indices:
            doc = valid_docs[idx] if threshold else self.documents[idx]
            score = float(similarities[idx])
            results.append((doc, score))

        return results

