        if not (200 <= resp.status_code < 300):
            raise RuntimeError(f"{method.upper()} {path} failed: {resp.status_code} {resp.text}")
        if response_text:
            return resp.text
        try:
            return resp.json()
        except Exception:
            return resp.text

