func mcpFetchSummary(ctx context.Context, client *api.Client, rawURL, lang string) (*episode.SummaryResult, error) {
	seq, err := episode.ParseSeq(rawURL)
	if err != nil {
		return nil, fmt.Errorf("invalid episode URL: %w", err)
	}
	language, err := episode.ResolveLangName(lang)
	if err != nil {
		return nil, err
	}
	return episode.FetchSummary(ctx, client, seq, false, language)
}

// Chamada: episode.ParseSeq(rawURL)
// Fonte (nível 3): internal/episode/utils.go:14-32
func ParseSeq(input string) (int, error) {
	const hint = "(expected https://podwise.ai/dashboard/episodes/<id>)"

	u, err := url.Parse(input)
	if err != nil || u.Scheme != "https" || !isPodwiseHost(u.Host) {
		return 0, fmt.Errorf("%q is not a valid podwise episode URL %s", input, hint)
	}

	parts := strings.Split(strings.Trim(u.Path, "/"), "/")
	if len(parts) != 3 || parts[0] != "dashboard" || parts[1] != "episodes" || parts[2] == "" {
		return 0, fmt.Errorf("%q is not a valid podwise episode URL %s", input, hint)
	}

	seq, err := strconv.Atoi(parts[2])
	if err != nil || seq <= 0 {
		return 0, fmt.Errorf("episode ID %q is not a positive integer %s", parts[2], hint)
	}
	return seq, nil
}

