// Fonte (nível 3): gateway/rdp/parser/parser.go:369-398
func (p *Parser) getError() string {
	results, err := p.fnGetErrorLen.Call(p.ctx)
	if err != nil {
		return ""
	}
	length := uint32(results[0])
	if length == 0 {
		return ""
	}

	results, err = p.fnGetError.Call(p.ctx)
	if err != nil {
		return ""
	}
	ptr := uint32(results[0])
	if ptr == 0 {
		return ""
	}

	buf, ok := p.memory.Read(ptr, length)
	if !ok {
		return ""
	}

	// Remove null terminator if present
	if len(buf) > 0 && buf[len(buf)-1] == 0 {
		buf = buf[:len(buf)-1]
	}
	return string(buf)
}

