    )

    body = {
        "Owner": {"Id": owner_id, "Type": "PERSON"},
        "Md5": file_md5,
        "Size": file_size,
        "Start": 0,
        "End": file_size - 1,
        "Crc": file_crc32,
    }

    result = _request(action="GetUploadState", service=SERVICE_MUSE, body=body)
    _check_resp(result, "GetUploadState")

    raw_state = result.get("Result", {})
    state: UploadStateResult = {
