def roots() -> list[str]:
    extra = os.environ.get("ANALYSIS_EXTRA_ROOTS", "")
    out = list(DEFAULT_ROOTS)
    for p in extra.split(os.pathsep):
        p = p.strip()
        if p:
            out.append(os.path.abspath(os.path.expanduser(p)))
    return out

