    def add(self, m: Match, is_home: bool) -> None:
        if m.home_goal is None or m.away_goal is None:
            return
        gf, ga = (m.home_goal, m.away_goal) if is_home else (m.away_goal, m.home_goal)
        self.played += 1
        self.goals_for += gf
        self.goals_against += ga
        if gf > ga:
            self.wins += 1
        elif gf < ga:
            self.losses += 1
        else:
            self.draws += 1

