def _extract_expected_kwargs_from_source(method: Callable[..., Any]) -> Optional[set]:
    try:
        src = inspect.getsource(method)
    except Exception:
        return None
    try:
        match = re.search(r"expected_kwargs\s*=\s*\[\s*(.*?)\s*\]", src, re.DOTALL)
