def _extract_field(row: object, field_path: str) -> object:
    """Walk a dotted field path on a proto-plus GoogleAdsRow."""
    obj = row
    for part in field_path.split("."):
        try:
            obj = getattr(obj, part)
        except AttributeError:
            return None
    return _to_python(obj)

