): TaskContractReadiness {
  if (!hasContractRules(rules)) {
    return {
      checked: false,
      ready: true,
      hasCanonicalStoryBlock: true,
      issues: [],
      loopBreakerThreshold: normalizeLoopBreakerThreshold(rules),
    };
