  private async recordTaskMoveBlockComment(
    task: Task,
    message: string,
    sessionId?: string,
  ): Promise<void> {
    const note = `Move blocked: ${message}`.trim();
    const lastComment = task.comments?.[task.comments.length - 1]?.body?.trim();
    if (lastComment === note) {
