pub(crate) fn record(
	tool: &str,
	subject: &str,
	namespace: Option<&str>,
	database: Option<&str>,
	outcome: Outcome,
	kind: &str,
	elapsed: Duration,
) {
	let time_ms = elapsed.as_secs_f64() * 1000.0;
	tracing::info!(
		target: "surrealdb::mcp::audit",
		tool,
		subject,
		namespace,
		database,
		outcome = outcome.as_str(),
		kind,
		time_ms,
		"mcp tool invocation"
	);
}

