        Title = "Search Economic Indicators",
        ReadOnly = true
    )]
    [Description(
        "Search the curated set of ~40 US macro FRED series Equibles tracks (rates, inflation, employment, GDP, housing, market indicators) — not the full FRED catalog. Search first requires every punctuation-independent query word anywhere across the series ID, title, or category, then broadens to any word only when that strict search has no rows. Standard names such as fed funds rate, jobless claims, payrolls, yield curve, and core CPI are recognized. An empty query lists every tracked series. Results include seasonal adjustment, the latest observation date, and the UTC time Equibles last synced the series."
    )]
    public Task<string> SearchEconomicIndicators(
        [Description(
            "Search query — series ID, title keyword, or category name (e.g., 'inflation', 'unemployment', 'GDP', 'FEDFUNDS'). Empty lists all tracked series."
        )]
            string query,
        [Description("Maximum number of results to return (default: 20, max: 500)")]
            int maxResults = 20
    )
    {
        return _runner.Execute(
            async () =>
            {
                maxResults = McpLimit.Clamp(maxResults);

                var matches = _seriesRepository.Search(query);
                var total = await matches.CountAsync();
                var series = await matches
                    .OrderBy(s => s.Category)
                    .ThenBy(s => s.SeriesId)
                    .Take(maxResults)
                    .ToListAsync();

                var title = string.IsNullOrWhiteSpace(query)
                    ? "All tracked economic indicator series:"
                    : $"Economic indicators matching '{query}':";

                var table = MarkdownTable.Render(
                    series,
                    $"No match for '{query}' in the tracked, curated ~40-series US macro set. This result describes only the tracked set, not whether FRED publishes such a series. Try fewer words, a category name, or an empty query to list every tracked series.",
                    title,
                    // Seasonal adjustment decides whether two series are even comparable. The
                    // ObservationEnd dates the newest data point; LastUpdated is the separate
                    // Equibles import clock. Both REST fields are rendered with distinct labels
                    // so a caller never mistakes ingestion freshness for publication recency.
                    "| Series ID | Title | Category | Frequency | Units | Seasonal Adj | Latest Observation | Last Synced (UTC) |",
                    "|-----------|-------|----------|-----------|-------|--------------|--------------------|-------------------|",
                    s =>
                        $"| {MarkdownTable.EscapeCell(s.SeriesId, "-")} | {MarkdownTable.EscapeCell(s.Title, "-")} | {MarkdownTable.EscapeCell(s.Category.ToString(), "-")} | {MarkdownTable.EscapeCell(s.Frequency, "-")} | {MarkdownTable.EscapeCell(s.Units, "-")} "
                        + $"| {MarkdownTable.EscapeCell(s.SeasonalAdjustment, "-")} "
                        + $"| {(s.ObservationEnd == null ? "-" : McpFormat.Invariant(s.ObservationEnd.Value, "yyyy-MM-dd"))} "
                        + $"| {McpFormat.OrDash(s.LastUpdated?.ToUniversalTime(), "O")} |"
                );

                var truncation = McpOutput.TruncationNote(series.Count, total);
                if (truncation.Length > 0)
                {
                    table += Environment.NewLine + truncation + Environment.NewLine;
                }

                return table;
            },
            "SearchEconomicIndicators",
            $"query: {query}"
        );
    }

