    public static string EscapeCell(string value, string emptyValue = "")
    {
        if (string.IsNullOrEmpty(value))
            return emptyValue;

        return value
            .Replace("\\", "\\\\")
            .Replace("|", "\\|")
            .Replace("\r", " ")
            .Replace("\n", " ");
    }

