            foreach (var member in trimmed.Members)
            {
                room -= Length(member);
                if (room < 0) break;

                kept++;
            }

            cut = MemberCut(kept, total);
            trimmed = trimmed with { Members = [.. trimmed.Members.Take(kept)] };
        }

        return trimmed with { Remarks = Note(trimmed, cut, maxLength) };
    }

