def _default_date_range(
    start: str, end: str
) -> tuple[str, str]:
    """Return (start, end) as YYYY-MM-DD strings, defaulting to last 30 days."""
    if not start or not end:
        today = date.today()
        return (today - timedelta(days=30)).isoformat(), today.isoformat()
    return start, end

