    kind = getattr(principal, "kind", None)
    if kind in ("user", "bridge", "mcp"):
        return kind  # type: ignore[return-value]
    # String-principal fallback: detect MCP by id prefix.
    pid = str(principal)
    if pid.startswith("mcp:"):
        return "mcp"
    if pid.startswith("bridge"):
        return "bridge"
    return "user"

