// Fonte (nível 3): src/beever_atlas/infra/channel_access.py:88-165
async def assert_channel_access(principal: Principal | str, channel_id: str) -> None:
    """Raise ``HTTPException(403)`` if ``principal`` cannot access ``channel_id``.

    See module docstring for the full decision table.
    """
    stores = get_stores()
    connections = await stores.platform.list_connections()
    matching = [c for c in connections if channel_id in (c.selected_channels or [])]

    pid = _principal_id(principal)
    kind = _principal_kind(principal)
    settings = get_settings()
    single_tenant = bool(getattr(settings, "beever_single_tenant", True))

    if not matching:
        # No connection explicitly claims this channel. `selected_channels`
        # is a sync pick-list, not the authoritative access list — a
        # single-tenant operator legitimately browses channels before
        # syncing them. Allow user AND mcp principals through in
        # single-tenant mode (the MCP api-key represents the same
        # single tenant); in multi-tenant mode the operator must have
        # explicitly claimed the channel via `selected_channels` on an
        # owned connection first. Bridge principals stay strict — they
        # can be cross-tenant.
        if single_tenant and kind in ("user", "mcp"):
            return
        logger.info(
            "channel_access deny: channel=%s principal=%s kind=%s reason=no_matching_connection",
            channel_id,
            pid,
            kind,
        )
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="Channel access denied",
        )

    # Explicit ownership match wins for both user and bridge principals.
    for conn in matching:
        owner = getattr(conn, "owner_principal_id", None)
        if owner and owner == pid:
            return

    # Single-tenant fallback: user AND mcp principals are admitted when
    # every matching row is un-owned or sentinel-owned. Bridge principals
    # stay strict (see the `kind == "bridge"` cross-tenant rationale in
    # assert_connection_owned). The MCP inclusion keeps this consistent
    # with list_connections and with assert_connection_owned so a caller
    # that can list a connection can also read the channels on it.
    if single_tenant and kind in ("user", "mcp"):
        all_legacy = all(
            (getattr(c, "owner_principal_id", None) in (None, _LEGACY_SHARED_OWNER))
            for c in matching
        )
        if all_legacy:
            return

    # Additional single-tenant fallback for MCP principals: dashboard-created
    # connections stamp ``owner_principal_id`` with a user principal id
    # (e.g. ``"user:<hash>"``), which the ``all_legacy`` branch above does
    # NOT admit. In single-tenant mode the MCP api-key represents the same
    # operator as the dashboard user, so MCP must still reach those rows.
    # Scoped to MCP only — user principals keep the stricter ``all_legacy``
    # check so two users in a single-tenant deployment don't see each
    # other's rows.
    if single_tenant and kind == "mcp":
        return

    logger.info(
        "channel_access deny: channel=%s principal=%s kind=%s reason=owner_mismatch",
        channel_id,
        pid,
        kind,
    )
    raise HTTPException(
        status_code=status.HTTP_403_FORBIDDEN,
        detail="Channel access denied",
    )

