    name = re.sub(r'\s*-?\s*[A-Z]{2}\s*$', '', name)
    # Remove content like "(antigo Esporte Clube Barreira) - RJ"
    name = re.sub(r'\(.*?\)\s*-?\s*[A-Z]{2}?\s*$', '', name)
